<?php
session_start();
require_once 'config.php';
$policies = require __DIR__ . '/bank_policies.php';
$fields = ['net_salary','requested_loan','existing_emi','proposed_emi','age','cibil_score','employment_months','experience_months','enq1','enq3','live_pl'];
$input = array_fill_keys($fields, '');
$input += ['employer_profile'=>'listed','cibil_type'=>'normal','payslip'=>'available','pg'=>'no','address'=>'available'];
$results=[]; $checked=false; $eligibleCount=0;
$num = function($k) use (&$input) { return (float)str_replace(',','',$input[$k] ?? 0); };
if ($_SERVER['REQUEST_METHOD']==='POST') {
    foreach ($input as $k=>$v) if (isset($_POST[$k])) $input[$k]=trim((string)$_POST[$k]);
    $salary=$num('net_salary'); $loan=$num('requested_loan'); $foir=$salary>0?($num('existing_emi')+$num('proposed_emi'))/$salary:0;
    $profile=$input['employer_profile']; $type=$input['cibil_type'];
    foreach($policies as $b){
        $bad=[];$review=[];$minSalary=$profile==='listed'?$b['salaryListed']:$b['salaryUnlisted'];$minCibil=$profile==='listed'?$b['cibilListed']:$b['cibilUnlisted'];
        if(!$loan||$loan<$b['min']||$loan>$b['max'])$bad[]=$loan>$b['max']?'Requested loan above bank maximum':'Requested loan below bank minimum';
        if(!$salary||$salary<$minSalary)$bad[]='Salary below policy minimum';
        if($type!=='normal'&&!$b['zeroOne'])$bad[]='CIBIL 0/-1 not allowed';
        if($type==='normal'&&(!$num('cibil_score')||$num('cibil_score')<$minCibil))$bad[]='CIBIL score below policy minimum';
        if(!$num('age')||$num('age')<$b['ageMin']||$num('age')>$b['ageMax'])$bad[]='Age outside policy range';
        if($b['profile']==='listed'&&$profile!=='listed')$bad[]='Unlisted employer not accepted';
        if($b['employment']&&$num('employment_months')<$b['employment'])$bad[]='Current employment below minimum';
        if($b['experience']&&$num('experience_months')<$b['experience'])$bad[]='Total experience below minimum';
        if($foir>$b['foir'])$bad[]='FOIR above policy limit';
        if($b['enq1']!==null&&$num('enq1')>$b['enq1'])$bad[]='1-month enquiries above limit';if($b['enq3']!==null&&$num('enq3')>$b['enq3'])$bad[]='3-month enquiries above limit';if($b['livePl']!==null&&$num('live_pl')>$b['livePl'])$bad[]='Live PL count above limit';
        if($b['payslip']==='required'&&$input['payslip']!=='available')$bad[]='Payslip required';if($b['pg']==='not_allowed'&&$input['pg']==='yes')$bad[]='PG accommodation not accepted';if($b['pg']==='review'&&$input['pg']==='yes')$review[]='PA/CPV may be required for PG';if($b['address']==='required'&&$input['address']!=='available')$bad[]='Current address proof required';
        $status=$bad?'NOT ELIGIBLE':($review?'REVIEW REQUIRED':'ELIGIBLE');if($status==='ELIGIBLE')$eligibleCount++;$results[]=array_merge($b,['status'=>$status,'reason'=>implode('; ',array_merge($bad,$review))?:'All entered checks passed']);
    }
    usort($results,function($a,$b){$o=['ELIGIBLE'=>1,'REVIEW REQUIRED'=>2,'NOT ELIGIBLE'=>3];return $o[$a['status']]<=>$o[$b['status']];});$checked=true;
}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function oldv($k,$a){return h($a[$k]??'');}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bank Eligibility Checker</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css" rel="stylesheet"><style>body{background:#f4f7fa}.hero{background:linear-gradient(135deg,#003366,#0066a1);color:#fff;padding:25px 0}.card{border:0;box-shadow:0 4px 16px #00336618}label{font-size:12px;font-weight:600;color:#38566b}.title{color:#003366;font-weight:700;border-bottom:2px solid #eaf4fb;padding-bottom:10px}.table thead th{background:#eaf4fb;color:#003366;white-space:nowrap}.status{font-size:11px}</style></head><body><div class="hero mb-4"><div class="container"><h2><i class="fas fa-university me-2"></i>Bank Eligibility Checker</h2><p class="mb-0">Compare customer details with all available personal-loan policies.</p></div></div><main class="container pb-5"><form method="post" class="card p-4"><h5 class="title"><i class="fas fa-user-check me-2"></i>Customer & Loan Details</h5><div class="row g-3">
<?php $defs=[['net_salary','Net Monthly Salary (₹)','text'],['requested_loan','Requested Loan (₹)','text'],['existing_emi','Existing Monthly EMI (₹)','text'],['proposed_emi','Proposed Loan EMI (₹)','text'],['age','Age','number'],['cibil_score','CIBIL Score','number'],['employment_months','Current Employment (months)','number'],['experience_months','Total Experience (months)','number'],['enq1','1M Enquiries','number'],['enq3','3M Enquiries','number'],['live_pl','Live PL Count','number']];foreach($defs as $d):?><div class="col-md-4"><label><?=h($d[1])?></label><input class="form-control" name="<?=$d[0]?>" type="<?=$d[2]?>" value="<?=oldv($d[0],$input)?>"></div><?php endforeach;?><div class="col-md-3"><label>Employer Profile</label><select class="form-select" name="employer_profile"><option value="listed" <?=$input['employer_profile']==='listed'?'selected':''?>>Listed</option><option value="unlisted" <?=$input['employer_profile']==='unlisted'?'selected':''?>>Unlisted</option></select></div><div class="col-md-3"><label>CIBIL Type</label><select class="form-select" name="cibil_type"><option value="normal" <?=$input['cibil_type']==='normal'?'selected':''?>>Normal</option><option value="zero" <?=$input['cibil_type']==='zero'?'selected':''?>>0</option><option value="minus1" <?=$input['cibil_type']==='minus1'?'selected':''?>>-1</option></select></div><div class="col-md-3"><label>Payslip</label><select class="form-select" name="payslip"><option value="available">Available</option><option value="not_available">Not available</option></select></div><div class="col-md-3"><label>PG Accommodation</label><select class="form-select" name="pg"><option value="no">No</option><option value="yes">Yes</option></select></div><div class="col-md-6"><label>Current Address Proof</label><select class="form-select" name="address"><option value="available">Available</option><option value="not_available">Not available</option></select></div></div><button type="submit" class="btn btn-primary mt-4 w-100"><i class="fas fa-search me-2"></i>Check Eligibility</button></form><div class="card p-4 mt-4"><div class="d-flex justify-content-between"><h5 class="title mb-0">Bank Results</h5><?php if($checked):?><span class="badge bg-success align-self-start"><?=$eligibleCount?> eligible</span><?php endif;?></div><div class="alert alert-info mt-3 small">Pre-screen only. Final approval is subject to the latest bank policy and credit approval.</div><div class="table-responsive"><table class="table table-sm table-bordered"><thead><tr><th>Rank</th><th>Bank</th><th>Status</th><th>Reason / Action</th><th>Loan Range</th><th>ROI</th><th>Tenure</th><th>FOIR</th></tr></thead><tbody><?php if(!$checked):?><tr><td colspan="8" class="text-center text-muted">Enter details and click Check Eligibility.</td></tr><?php else:foreach($results as $i=>$b):$c=$b['status']==='ELIGIBLE'?'bg-success':($b['status']==='REVIEW REQUIRED'?'bg-warning text-dark':'bg-danger');?><tr><td><?=$i+1?></td><td><strong><?=h($b['name'])?></strong></td><td><span class="badge status <?=$c?>"><?=h($b['status'])?></span></td><td><?=h($b['reason'])?></td><td>₹<?=number_format($b['min'])?> - ₹<?=number_format($b['max'])?></td><td><?=h($b['roi'])?></td><td><?=h($b['tenure'])?></td><td><?=round($b['foir']*100)?>%</td></tr><?php endforeach;endif;?></tbody></table></div></div></main></body></html>
